function adapt(input, solve, kit) {
  const [values] = input;
  const root = kit.toTree(values);
  // Collect the original nodes with an explicit stack so deep trees need no recursion here.
  const nodes = [];
  const stack = root ? [root] : [];
  while (stack.length) {
    const node = stack.pop();
    nodes.push(node);
    if (node.right) stack.push(node.right);
    if (node.left) stack.push(node.left);
  }
  const head = solve(root);
  if (head === undefined) throw new Error('The solution did not return a value.');
  if (nodes.length === 0) {
    if (head !== null) throw new Error('An empty tree gives null.');
    return [];
  }
  const original = new Set(nodes);
  if (!original.has(head)) throw new Error('Return a node of the tree; do not create new nodes.');
  // Walk right from the head once around the circle, checking each left link on the way.
  const out = [];
  const visited = new Set();
  let node = head;
  do {
    if (!original.has(node)) throw new Error('Every right link must point to a node of the tree.');
    if (visited.has(node)) throw new Error('Following right comes back to a node before reaching the head again.');
    visited.add(node);
    if (node.right === null || node.right === undefined) throw new Error('The list must be circular: no right link may be null.');
    if (node.right.left !== node) throw new Error('Each node\'s right neighbour must point back to it through left.');
    out.push(node.val);
    node = node.right;
  } while (node !== head);
  if (out.length !== nodes.length) throw new Error('The list must contain every node of the tree.');
  return out;
}

