function treeToDoublyList(root) {
  if (root === null) {
    return null;
  }
  const stack = [];
  let first = null;
  let last = null;
  let node = root;
  while (node !== null || stack.length > 0) {
    while (node !== null) {
      stack.push(node);
      node = node.left;
    }
    node = stack.pop();
    if (last === null) {
      first = node;
    } else {
      last.right = node;
      node.left = last;
    }
    last = node;
    node = node.right;
  }
  last.right = first;
  first.left = last;
  return first;
}

