function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 900 + pick(90) : pick(9);
  const span = large || rand() < 0.5 ? 1000 : 12;
  const used = new Set();
  const keys = [];
  while (keys.length < n) {
    const v = pick(2 * span + 1) - span;
    if (!used.has(v)) { used.add(v); keys.push(v); }
  }
  // Random insertion order gives a bushy tree; sorted or reversed order gives a chain.
  const shape = pick(4);
  if (shape === 2) keys.sort((a, b) => a - b);
  if (shape === 3) keys.sort((a, b) => b - a);
  let root = null;
  for (const val of keys) {
    const fresh = { val, left: null, right: null };
    if (!root) { root = fresh; continue; }
    let node = root;
    for (;;) {
      const side = val < node.val ? 'left' : 'right';
      if (!node[side]) { node[side] = fresh; break; }
      node = node[side];
    }
  }
  const level = [];
  const queue = [root];
  for (let k = 0; k < queue.length; k++) {
    level.push(queue[k] ? queue[k].val : null);
    if (queue[k]) queue.push(queue[k].left, queue[k].right);
  }
  while (level.length && level[level.length - 1] === null) level.pop();
  return [level];
}
